using namespace std;

int main() {
    int n;
    while(cin >> n) {
        if(n < 2) {
            cout << 0 << endl;
            continue;
        }

        int sum = 0;
        vector<bool> judge(n + 1, true); // Use vector of size n + 1
        judge[0] = judge[1] = false; // 0 and 1 are not prime

        for(int i = 2; i <= sqrt(n); ++i) {
            if (judge[i]) {
                for (int j = i * i; j <= n; j += i) {
                    judge[j] = false; // Mark multiples as non-prime
                }
            }
        }

        for (int i = 2; i <= n; ++i) {
            if (judge[i]) {
                sum++;
            }
        }

        cout << sum << endl;
    }

    return 0;
}

